package org.jarvisassistant.app;
import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.concurrent.*;

/** Watch-sized views of actual laptop files, coding activity and explicit controls. */
public final class WatchToolsActivity extends Activity {
    private final Handler main=new Handler(Looper.getMainLooper());private final ExecutorService worker=Executors.newSingleThreadExecutor();private volatile WatchRpc active;private LinearLayout body;private TextView status;private boolean visible,busy;private int epoch;private String tool,share="",path="";private int offset;private int pendingX,pendingY;private long movedAt;
    private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
    @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);tool=getIntent().getStringExtra("tool");if(!java.util.Arrays.asList("files","coding","remote").contains(tool)){finish();return;}layout(tool.equals("files")?"Laptop files":tool.equals("coding")?"Codex sessions":"Laptop controls");}
    private TextView text(String value,int size,int color){return WatchStyle.text(this,value,size,color);}
    private void layout(String title){body=WatchStyle.page(this,title);status=text("Connecting through your phone…",12,WatchStyle.MUTED);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);body.addView(status,new LinearLayout.LayoutParams(-1,-2));}
    private Button button(String label,boolean primary,Runnable run){return WatchStyle.addButton(body,label,primary,()->{if(!busy)run.run();});}
    private interface Result{void show(JSONObject value)throws Exception;}
    private void request(String operation,JSONObject args,Result result){if(!visible||busy)return;busy=true;int generation=epoch;status.setText("Connecting…");worker.execute(()->{try(WatchRpc client=new WatchRpc(this)){active=client;JSONObject value=client.json(operation,args);main.post(()->{if(!visible||generation!=epoch)return;busy=false;try{result.show(value);}catch(Exception error){status.setText("That view could not be displayed. Try again.");}});}catch(Exception error){main.post(()->{if(visible&&generation==epoch){busy=false;status.setText(error.getMessage()==null?"Connection interrupted. Nothing was resent.":error.getMessage());}});}finally{active=null;}});}
    private void open(){if(tool.equals("files"))files();else if(tool.equals("coding"))coding();else remote();}
    private void files(){layout(path.isEmpty()?"Laptop files":path.substring(path.lastIndexOf('/')+1));button("Back",false,()->{if(share.isEmpty()){finish();return;}if(path.isEmpty()){share="";offset=0;}else{int slash=path.lastIndexOf('/');path=slash<0?"":path.substring(0,slash);offset=0;}files();});button("Try again",false,this::files);
        try{if(share.isEmpty())request("files.roots",new JSONObject(),value->{status.setText("Choose a drive");JSONArray shares=value.getJSONArray("shares");for(int i=0;i<shares.length();i++){JSONObject item=shares.getJSONObject(i);button(item.getString("label"),false,()->{share=item.optString("id");path="";offset=0;files();});}if(shares.length()==0)status.setText("No laptop drives are available.");});else request("files.list",new JSONObject().put("share",share).put("path",path).put("offset",offset),value->{JSONArray entries=value.getJSONArray("entries");status.setText(entries.length()==0?"This folder is empty":"Tap a folder or file");for(int i=0;i<entries.length();i++){JSONObject entry=entries.getJSONObject(i);String name=entry.getString("name");boolean folder=entry.optBoolean("directory");button((folder?"▸ ":"")+name,false,()->{if(folder){path=path.isEmpty()?name:path+"/"+name;offset=0;files();}else file(entry);});}if(!value.isNull("next"))button("More files",false,()->{offset=value.optInt("next");files();});if(offset>0)button("First page",false,()->{offset=0;files();});if(value.optBoolean("truncated"))body.addView(text("This folder has more entries than the current listing limit. Open it on your phone for the full view.",12,0xff9daab9));});}catch(Exception error){status.setText("Choose a folder again.");}
    }
    private void file(JSONObject entry){layout(entry.optString("name"));status.setText(android.text.format.Formatter.formatFileSize(this,entry.optLong("bytes")));body.addView(text("Modified "+entry.optString("modified").replace('T',' ').replace('Z',' '),12,0xff9daab9));button("Download on phone",true,()->{try{request("files.phone-download",new JSONObject().put("share",share).put("path",path.isEmpty()?entry.optString("name"):path+"/"+entry.optString("name")).put("name",entry.optString("name")),value->status.setText(value.optString("message","Open the phone notification to choose where to save it.")));}catch(Exception ignored){}});button("Back to folder",false,this::files);}
    private void coding(){layout("Codex sessions");button("Check again",false,this::coding);button("Back",false,this::finish);request("coding.list",new JSONObject(),value->{JSONArray sessions=value.getJSONArray("sessions");status.setText(value.optBoolean("enabled")?(sessions.length()==0?"No recent sessions":"Current coding activity"):value.optString("message","Coding monitoring is paused."));for(int i=0;i<sessions.length();i++){JSONObject item=sessions.getJSONObject(i);button(item.optString("title"),false,()->new AlertDialog.Builder(this).setTitle(item.optString("title")).setMessage(item.optString("status")+"\n\n"+item.optString("detail")).setPositiveButton("Done",null).show());}body.addView(text("Approvals stay in Codex. This screen shows session progress.",12,0xff9daab9));});}
    private void remote(){layout("Laptop controls");status.setText("Use your unlocked watch. No 15-minute grant.");String[] labels={"Play / pause","Previous track","Next track","Volume +","Volume −","Mute"},keys={"play-pause","previous","next","volume-up","volume-down","mute"};for(int i=0;i<labels.length;i++){String key=keys[i];button(labels[i],i==0,()->input("media","key",key));}button("Mouse & keyboard",false,this::pointer);button("Windows lock / unlock",false,()->{WatchConnection.phone(this,node->{try{WearableMessage.send(this,node,"computer");status.setText("Review the phone notification for fingerprint approval.");}catch(Exception error){status.setText("Phone request could not be sent.");}},error->status.setText(error));});button("Back",false,this::finish);}
    private void input(String type,String key,String value){try{request("remote.input",new JSONObject().put("events",new JSONArray().put(new JSONObject().put("type",type).put(key,value))),result->status.setText("Applied"));}catch(Exception ignored){}}
    private void pointer(){layout("Mouse & keyboard");status.setText("Drag to move · tap to click");WatchTouchpad pad=new WatchTouchpad(this,new WatchTouchpad.Input(){public void move(int x,int y){pendingX=Math.max(-600,Math.min(600,pendingX+x));pendingY=Math.max(-600,Math.min(600,pendingY+y));movedAt=SystemClock.elapsedRealtime();main.removeCallbacks(flushPointer);main.postDelayed(flushPointer,90);}public void click(){input("click","button","left");}public void scroll(int steps){try{request("remote.input",new JSONObject().put("events",new JSONArray().put(new JSONObject().put("type","scroll").put("steps",steps))),result->status.setText("Scrolled"));}catch(Exception ignored){}}});body.addView(pad,new LinearLayout.LayoutParams(-1,dp(112)));int[][] moves={{0,-45},{-45,0},{45,0},{0,45}};String[] labels={"↑","←","→","↓"};for(int i=0;i<labels.length;i++){int x=moves[i][0],y=moves[i][1];button(labels[i],false,()->{try{request("remote.input",new JSONObject().put("events",new JSONArray().put(new JSONObject().put("type","move").put("x",x).put("y",y))),result->status.setText("Pointer moved"));}catch(Exception ignored){}});}button("Click",true,()->input("click","button","left"));button("Right click",false,()->input("click","button","right"));EditText message=new EditText(this);message.setTextColor(Color.WHITE);message.setHintTextColor(0xff9daab9);message.setHint("Type on laptop");message.setMaxLines(3);body.addView(message);button("Send text",true,()->{String text=message.getText().toString();if(text.length()>512){status.setText("Send up to 512 characters at a time.");return;}input("text","text",text);});button("Enter",false,()->input("key","key","enter"));button("Back",false,this::remote);}
    private final Runnable flushPointer=new Runnable(){public void run(){if(!visible||SystemClock.elapsedRealtime()-movedAt>1200){pendingX=pendingY=0;return;}if(busy){main.postDelayed(this,100);return;}int x=pendingX,y=pendingY;pendingX=pendingY=0;if(x==0&&y==0)return;try{request("remote.input",new JSONObject().put("events",new JSONArray().put(new JSONObject().put("type","move").put("x",x).put("y",y))),result->status.setText("Pointer moved"));}catch(Exception ignored){}}};
    @Override protected void onResume(){super.onResume();visible=true;busy=false;open();}
    @Override protected void onPause(){visible=false;main.removeCallbacks(flushPointer);pendingX=pendingY=0;epoch++;WatchRpc client=active;if(client!=null)client.close();busy=false;super.onPause();}
    @Override protected void onDestroy(){worker.shutdownNow();main.removeCallbacksAndMessages(null);super.onDestroy();}
}
